1	/**
2	 * InkOS Payments — RPC + DB row contracts (Sprint 13)
3	 *
4	 * Source of truth for the dual-stack payment system.
5	 *   • L1 — Dodo Payments (SaaS subscriptions, MoR-handled global tax). Existing.
6	 *   • L2 — Stripe Connect Express (in-studio marketplace, NEW from Sprint 13).
7	 *
8	 * EVERY RPC SIGNATURE LIVES HERE BEFORE DATO WRITES THE MIGRATION.
9	 * Param-name drift between TS and SQL is the #1 InkOS bug source (per inkos-lessons §1).
10	 *
11	 * Money is ALWAYS stored as `cents INT`. Never numeric. Never float.
12	 * Banker's rounding when splitting.
13	 *
14	 * Owner: inkos-payments-lead (.claude/agents/inkos-payments-lead.md)
15	 */
16	
17	// =====================================================================
18	// PRIMITIVE TYPES
19	// =====================================================================
20	
21	/** ISO 4217 lowercase currency code as used by Stripe. Lock the supported set. */
22	export type Currency = 'usd' | 'gbp' | 'eur' | 'aud' | 'cad';
23	
24	/**
25	 * Money expressed as integer minor units (cents, pence, etc).
26	 * Branded so a raw `number` can't be passed where money is expected.
27	 */
28	export type CentsAmount = number & { readonly __brand: 'CentsAmount' };
29	
30	/** Construct a CentsAmount with bounds checking. Negative amounts allowed for refunds/reversals. */
31	export function cents(value: number): CentsAmount {
32	  if (!Number.isInteger(value)) {
33	    throw new Error(`CentsAmount must be integer, got ${value}`);
34	  }
35	  return value as CentsAmount;
36	}
37	
38	/**
39	 * Idempotency key carried in Stripe metadata for webhook reconciliation.
40	 * UUID v4 generated at call site; same key reused on retry of same logical operation.
41	 */
42	export type InkosIdempotencyKey = string & { readonly __brand: 'InkosIdempotencyKey' };
43	
44	/** Webhook event source — used in `webhook_events.source` UNIQUE constraint. */
45	export type WebhookSource = 'dodo' | 'stripe';
46	
47	// =====================================================================
48	// ENUMS — mirror SQL CHECK constraints
49	// =====================================================================
50	
51	/** Stripe Connect Express account type. One per studio (mandatory) + optional one per artist. */
52	export type ConnectedAccountType = 'studio' | 'artist';
53	
54	/** Connect onboarding lifecycle. Updated by `account.updated` webhook. */
55	export type ConnectedAccountOnboardingStatus =
56	  | 'pending'    // account created, KYC not started
57	  | 'active'     // charges_enabled && payouts_enabled
58	  | 'restricted' // partially complete; some capabilities disabled
59	  | 'rejected';  // permanently blocked by Stripe
60	
61	/** Stripe charge lifecycle (mirrored from PaymentIntent status). */
62	export type StripeChargeStatus =
63	  | 'requires_payment_method'
64	  | 'requires_confirmation'
65	  | 'requires_action'
66	  | 'processing'
67	  | 'requires_capture'
68	  | 'canceled'
69	  | 'succeeded'
70	  | 'refunded'
71	  | 'partially_refunded';
72	
73	/** Dispute lifecycle. */
74	export type StripeDisputeStatus =
75	  | 'warning_needs_response'
76	  | 'warning_under_review'
77	  | 'warning_closed'
78	  | 'needs_response'
79	  | 'under_review'
80	  | 'won'
81	  | 'lost'
82	  | 'charge_refunded';
83	
84	/** Defense pack assembly + submission status. */
85	export type DisputeDefensePackStatus =
86	  | 'pending'    // BullMQ job not yet run
87	  | 'assembling' // job running, gathering documents
88	  | 'ready'      // bundle PDF generated, awaiting submission
89	  | 'submitted'  // sent to Stripe via /v1/disputes/:id
90	  | 'failed';    // assembly or submission errored
91	
92	/** Commission split kind — distinguishes original split from reversal. */
93	export type CommissionSplitKind =
94	  | 'split'      // original 70/30 split on session settlement
95	  | 'reversal'   // reverses a prior split (refund, dispute lost)
96	  | 'adjustment' // manual correction (rare, audit-logged)
97	  | 'tip';       // tip-only transfer (separate row from base split)
98	
99	/** Tax remittance ledger row status. */
100	export type TaxRemittanceStatus =
101	  | 'open'           // collected this period, not yet remitted
102	  | 'manual_review'  // Stripe Tax API failed or jurisdiction not supported
103	  | 'filed'          // remittance filed with tax authority
104	  | 'paid';          // payment cleared
105	
106	/** 1099-NEC export source — Stripe-issued vs InkOS-internal calc. */
107	export type Nec1099Source = 'stripe' | 'inkos_internal';
108	
109	// =====================================================================
110	// TABLE ROW TYPES — shape Dato's CREATE TABLE statements must produce
111	// =====================================================================
112	
113	/**
114	 * `webhook_events` — first write of every webhook handler.
115	 * UNIQUE (source, event_id) drives idempotency.
116	 * `INSERT ... ON CONFLICT (source, event_id) DO NOTHING` returns 200 immediately on replay.
117	 */
118	export interface WebhookEventRow {
119	  id: string;                     // UUID
120	  source: WebhookSource;          // 'dodo' | 'stripe'
121	  event_id: string;               // provider's event id
122	  event_type: string;             // e.g. 'payment_intent.succeeded'
123	  payload: unknown;               // JSONB — raw webhook body
124	  signature_verified: boolean;    // result of HMAC check
125	  processed_at: string | null;    // timestamptz; null until handler completes
126	  error: string | null;           // last error message if retried
127	  retry_count: number;            // incremented by replay queue
128	  created_at: string;             // timestamptz
129	}
130	
131	/**
132	 * `stripe_connected_accounts` — one per studio (mandatory) + optional one per artist.
133	 * Studio's account is the platform's destination for in-studio charges.
134	 * Artist accounts let artists receive direct payouts (bypassing studio float).
135	 */
136	export interface StripeConnectedAccountRow {
137	  id: string;                                            // UUID
138	  studio_id: string;                                     // FK
139	  account_id: string;                                    // Stripe acct_xxx
140	  type: ConnectedAccountType;                            // 'studio' | 'artist'
141	  artist_id: string | null;                              // FK, NULL when type='studio'
142	  onboarding_status: ConnectedAccountOnboardingStatus;
143	  capabilities: {
144	    charges_enabled: boolean;
145	    payouts_enabled: boolean;
146	    transfers: boolean;
147	    tax_reporting_us_1099_nec: boolean;
148	    [k: string]: boolean | undefined;
149	  };
150	  country: string;                                       // ISO 3166-1 alpha-2
151	  default_currency: Currency;
152	  restricted_reason: string | null;
153	  requirements_due_by: string | null;                    // timestamptz
154	  created_at: string;
155	  updated_at: string;
156	}
157	
158	/**
159	 * `stripe_charges` — mirror of every PaymentIntent we initiate.
160	 * idempotency_key UNIQUE prevents duplicate writes on webhook replay.
161	 * Money in CentsAmount, currency separate (no implicit USD).
162	 */
163	export interface StripeChargeRow {
164	  id: string;
165	  studio_id: string;
166	  payment_intent_id: string;                  // pi_xxx
167	  charge_id: string | null;                   // ch_xxx (null until succeeded)
168	  transfer_id: string | null;                 // tr_xxx (null on pool-only charges)
169	  application_fee_id: string | null;          // fee_xxx
170	  status: StripeChargeStatus;
171	  currency: Currency;
172	  amount_cents: CentsAmount;                  // total client paid (incl tax + tip)
173	  tax_amount_cents: CentsAmount;              // recorded by Stripe Tax
174	  application_fee_cents: CentsAmount;         // studio's commission
175	  net_artist_cents: CentsAmount;              // amount_cents - tax - application_fee - tip (split base)
176	  tip_amount_cents: CentsAmount;              // tip routed separately, 100% to artist by default
177	  booking_id: string | null;
178	  project_id: string | null;
179	  session_id: string | null;
180	  client_id: string | null;
181	  deposit_drawdown_cents: CentsAmount;        // pool draw applied to this charge (0 if none)
182	  idempotency_key: InkosIdempotencyKey;       // UNIQUE
183	  presentment_currency: Currency | null;      // for cross-border FX
184	  presentment_amount_cents: CentsAmount | null;
185	  created_at: string;
186	}
187	
188	/**
189	 * `stripe_disputes` — mirrors Stripe disputes; defense pack assembled async.
190	 */
191	export interface StripeDisputeRow {
192	  id: string;
193	  studio_id: string;
194	  dispute_id: string;                         // dp_xxx
195	  charge_id: string;                          // ch_xxx (FK to stripe_charges.charge_id)
196	  reason: string;                             // Stripe's reason code
197	  status: StripeDisputeStatus;
198	  amount_cents: CentsAmount;
199	  currency: Currency;
200	  evidence_due_by: string;                    // timestamptz — submit 24h before
201	  defense_pack_status: DisputeDefensePackStatus;
202	  defense_pack_url: string | null;            // signed Storage URL of bundle PDF
203	  submitted_at: string | null;
204	  resolved_at: string | null;
205	  resolved_amount_cents: CentsAmount | null;  // final clawback if lost
206	  created_at: string;
207	}
208	
209	/**
210	 * `tax_remittance_ledger` — quarterly tax accumulator per studio per location per jurisdiction.
211	 * Reconciles to Stripe Tax reports within $0.01.
212	 */
213	export interface TaxRemittanceLedgerRow {
214	  id: string;
215	  studio_id: string;
216	  location_id: string;
217	  jurisdiction: string;                       // e.g. 'US-NY-NYC', 'GB', 'EU-DE'
218	  period: string;                             // e.g. '2026-Q2', '2026-04'
219	  amount_collected_cents: CentsAmount;
220	  amount_remitted_cents: CentsAmount;
221	  remittance_date: string | null;
222	  remittance_reference: string | null;        // confirmation # from tax authority
223	  status: TaxRemittanceStatus;
224	  created_at: string;
225	  updated_at: string;
226	}
227	
228	/**
229	 * `commission_splits` — one row per artist payout per session settlement.
230	 * Reversals reference parent_split_id for refund/dispute proportional clawback.
231	 */
232	export interface CommissionSplitRow {
233	  id: string;
234	  studio_id: string;
235	  booking_id: string | null;
236	  session_id: string | null;
237	  artist_id: string;
238	  base_amount_cents: CentsAmount;             // pre-fee artist share
239	  commission_pct: number;                     // 0.00–100.00 (numeric in DB but bounded)
240	  tip_amount_cents: CentsAmount;              // separate row when kind='tip'
241	  applied_from_pool_cents: CentsAmount;       // pool drawdown in this split
242	  stripe_transfer_id: string | null;          // tr_xxx (null on pool-only splits)
243	  kind: CommissionSplitKind;
244	  parent_split_id: string | null;             // for reversals
245	  created_at: string;
246	}
247	
248	/**
249	 * `dispute_defense_packs` — bundled evidence PDF + provenance trail.
250	 */
251	export interface DisputeDefensePackRow {
252	  id: string;
253	  dispute_id: string;
254	  signed_consent_url: string | null;
255	  photo_release_url: string | null;
256	  session_photos_urls: string[];
257	  chat_history_url: string | null;
258	  deposit_policy_text: string;
259	  receipt_url: string | null;
260	  bundle_pdf_url: string | null;
261	  generated_at: string;
262	}
263	
264	/**
265	 * `nec_1099_exports` — annual 1099-NEC export per artist.
266	 * Stripe-issued (preferred) cross-checked against InkOS-internal calc from commission_splits.
267	 */
268	export interface Nec1099ExportRow {
269	  id: string;
270	  studio_id: string;
271	  year: number;
272	  artist_id: string;
273	  total_paid_cents: CentsAmount;
274	  federal_id_last4: string | null;
275	  state_id_last4: string | null;
276	  csv_url: string | null;
277	  pdf_url: string | null;
278	  source: Nec1099Source;                      // 'stripe' | 'inkos_internal'
279	  generated_at: string;
280	}
281	
282	// =====================================================================
283	// RPC CONTRACTS — exact signatures Dato implements in SQL
284	// =====================================================================
285	// Each RPC has: name, args interface, return type.
286	// SQL function name MATCHES the constant string literal `RPC.<NAME>`.
287	// SQL parameter names MATCH camelCase → snake_case translation:
288	//   args.studioId → p_studio_id (Postgres convention).
289	// Drift between this file and SQL is a P0 bug — Sage scans match.
290	
291	export const RPC = {
292	  WEBHOOK_EVENT_INSERT: 'webhook_event_insert',
293	  STRIPE_CONNECTED_ACCOUNT_CREATE: 'stripe_connected_account_create',
294	  STRIPE_CONNECTED_ACCOUNT_UPDATE_FROM_WEBHOOK: 'stripe_connected_account_update_from_webhook',
295	  STRIPE_CHARGE_RECORD: 'stripe_charge_record',
296	  STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK: 'stripe_charge_update_status_from_webhook',
297	  COMMISSION_SPLIT_RECORD: 'commission_split_record',
298	  COMMISSION_SPLIT_REVERSE: 'commission_split_reverse',
299	  STRIPE_DISPUTE_RECORD: 'stripe_dispute_record',
300	  STRIPE_DISPUTE_UPDATE_STATUS_FROM_WEBHOOK: 'stripe_dispute_update_status_from_webhook',
301	  DISPUTE_DEFENSE_PACK_RECORD: 'dispute_defense_pack_record',
302	  TAX_REMITTANCE_ACCRUE: 'tax_remittance_accrue',
303	  TAX_REMITTANCE_FILE: 'tax_remittance_file',
304	  NEC_1099_EXPORT_RECORD: 'nec_1099_export_record',
305	} as const;
306	
307	// ---------- webhook_event_insert ----------
308	
309	/** Idempotently insert a webhook event. Returns true if newly inserted, false if conflict (replay). */
310	export interface WebhookEventInsertArgs {
311	  source: WebhookSource;
312	  eventId: string;
313	  eventType: string;
314	  payload: unknown;
315	  signatureVerified: boolean;
316	}
317	export type WebhookEventInsertResult = { inserted: boolean; id: string | null };
318	
319	// ---------- stripe_connected_account_create ----------
320	
321	export interface StripeConnectedAccountCreateArgs {
322	  studioId: string;
323	  type: ConnectedAccountType;
324	  artistId: string | null;
325	  accountId: string;                 // Stripe acct_xxx
326	  country: string;                   // ISO 3166-1 alpha-2
327	  defaultCurrency: Currency;
328	}
329	export type StripeConnectedAccountCreateResult = { id: string };
330	
331	// ---------- stripe_connected_account_update_from_webhook ----------
332	
333	/** Updates onboarding_status + capabilities on `account.updated` webhook. Idempotent. */
334	export interface StripeConnectedAccountUpdateFromWebhookArgs {
335	  accountId: string;
336	  onboardingStatus: ConnectedAccountOnboardingStatus;
337	  capabilities: StripeConnectedAccountRow['capabilities'];
338	  country: string;
339	  defaultCurrency: Currency;
340	  restrictedReason: string | null;
341	  requirementsDueBy: string | null;
342	}
343	export type StripeConnectedAccountUpdateFromWebhookResult = { id: string; status: ConnectedAccountOnboardingStatus };
344	
345	// ---------- stripe_charge_record ----------
346	
347	/**
348	 * Insert a stripe_charges row at PaymentIntent creation time.
349	 * Idempotent on idempotency_key — same key returns existing row id.
350	 */
351	export interface StripeChargeRecordArgs {
352	  studioId: string;
353	  paymentIntentId: string;
354	  status: StripeChargeStatus;
355	  currency: Currency;
356	  amountCents: CentsAmount;
357	  taxAmountCents: CentsAmount;
358	  applicationFeeCents: CentsAmount;
359	  netArtistCents: CentsAmount;
360	  tipAmountCents: CentsAmount;
361	  bookingId: string | null;
362	  projectId: string | null;
363	  sessionId: string | null;
364	  clientId: string | null;
365	  depositDrawdownCents: CentsAmount;
366	  idempotencyKey: InkosIdempotencyKey;
367	  presentmentCurrency: Currency | null;
368	  presentmentAmountCents: CentsAmount | null;
369	}
370	export type StripeChargeRecordResult = { id: string; created: boolean };
371	
372	// ---------- stripe_charge_update_status_from_webhook ----------
373	
374	export interface StripeChargeUpdateStatusFromWebhookArgs {
375	  paymentIntentId: string;
376	  status: StripeChargeStatus;
377	  chargeId: string | null;
378	  transferId: string | null;
379	  applicationFeeId: string | null;
380	}
381	export type StripeChargeUpdateStatusFromWebhookResult = { id: string; status: StripeChargeStatus };
382	
383	// ---------- commission_split_record ----------
384	
385	export interface CommissionSplitRecordArgs {
386	  studioId: string;
387	  bookingId: string | null;
388	  sessionId: string | null;
389	  artistId: string;
390	  baseAmountCents: CentsAmount;
391	  commissionPct: number;
392	  tipAmountCents: CentsAmount;
393	  appliedFromPoolCents: CentsAmount;
394	  stripeTransferId: string | null;
395	  kind: CommissionSplitKind;
396	}
397	export type CommissionSplitRecordResult = { id: string };
398	
399	// ---------- commission_split_reverse ----------
400	
401	/**
402	 * Reverses a prior split (refund, dispute lost).
403	 * Inserts a new row with kind='reversal' and parent_split_id = original.
404	 * Returns the reversal row id.
405	 */
406	export interface CommissionSplitReverseArgs {
407	  parentSplitId: string;
408	  reverseAmountCents: CentsAmount;          // can be partial
409	  reverseTipCents: CentsAmount;
410	  reverseStripeTransferId: string | null;
411	}
412	export type CommissionSplitReverseResult = { id: string };
413	
414	// ---------- stripe_dispute_record ----------
415	
416	export interface StripeDisputeRecordArgs {
417	  studioId: string;
418	  disputeId: string;
419	  chargeId: string;
420	  reason: string;
421	  status: StripeDisputeStatus;
422	  amountCents: CentsAmount;
423	  currency: Currency;
424	  evidenceDueBy: string;
425	}
426	export type StripeDisputeRecordResult = { id: string };
427	
428	// ---------- stripe_dispute_update_status_from_webhook ----------
429	
430	export interface StripeDisputeUpdateStatusFromWebhookArgs {
431	  disputeId: string;
432	  status: StripeDisputeStatus;
433	  resolvedAt: string | null;
434	  resolvedAmountCents: CentsAmount | null;
435	}
436	export type StripeDisputeUpdateStatusFromWebhookResult = { id: string; status: StripeDisputeStatus };
437	
438	// ---------- dispute_defense_pack_record ----------
439	
440	export interface DisputeDefensePackRecordArgs {
441	  disputeId: string;
442	  signedConsentUrl: string | null;
443	  photoReleaseUrl: string | null;
444	  sessionPhotosUrls: string[];
445	  chatHistoryUrl: string | null;
446	  depositPolicyText: string;
447	  receiptUrl: string | null;
448	  bundlePdfUrl: string | null;
449	}
450	export type DisputeDefensePackRecordResult = { id: string };
451	
452	// ---------- tax_remittance_accrue ----------
453	
454	/**
455	 * Increments tax_remittance_ledger.amount_collected_cents for the matching
456	 * (studio, location, jurisdiction, period). Creates row if not exists.
457	 */
458	export interface TaxRemittanceAccrueArgs {
459	  studioId: string;
460	  locationId: string;
461	  jurisdiction: string;
462	  period: string;
463	  amountCollectedCents: CentsAmount;
464	}
465	export type TaxRemittanceAccrueResult = { id: string; new_total_cents: CentsAmount };
466	
467	// ---------- tax_remittance_file ----------
468	
469	export interface TaxRemittanceFileArgs {
470	  ledgerId: string;
471	  amountRemittedCents: CentsAmount;
472	  remittanceDate: string;
473	  remittanceReference: string;
474	}
475	export type TaxRemittanceFileResult = { id: string; status: TaxRemittanceStatus };
476	
477	// ---------- nec_1099_export_record ----------
478	
479	export interface Nec1099ExportRecordArgs {
480	  studioId: string;
481	  year: number;
482	  artistId: string;
483	  totalPaidCents: CentsAmount;
484	  federalIdLast4: string | null;
485	  stateIdLast4: string | null;
486	  csvUrl: string | null;
487	  pdfUrl: string | null;
488	  source: Nec1099Source;
489	}
490	export type Nec1099ExportRecordResult = { id: string };
491	
492	// =====================================================================
493	// PRESET SPLIT PERCENTAGES (locked defaults — overridable per studio)
494	// =====================================================================
495	
496	export const DEFAULT_COMMISSION_PCT = {
497	  RESIDENT_ESTABLISHED: 70,    // 70/30 in artist's favor
498	  RESIDENT_NEW: 60,            // 60/40
499	  RESIDENT_FULL_SUPPORT: 50,   // 50/50 when shop covers everything
500	  GUEST: 80,                   // 80/20 in guest's favor
501	  APPRENTICE: 50,              // 50/50 ramp
502	  BOOTH_RENTER: 100,           // booth renter keeps everything (rent invoiced separately)
503	} as const;
504	
505	// =====================================================================
506	// INVARIANTS — Sage scans verify these hold across the codebase
507	// =====================================================================
508	
509	/**
510	 * INVARIANT 1: All money is CentsAmount. Never `number` for money.
511	 * INVARIANT 2: Every Stripe call carries `metadata.inkos_idempotency_key`.
512	 * INVARIANT 3: Every webhook handler's first write is webhook_event_insert.
513	 * INVARIANT 4: `application_fee_amount` is set on every PaymentIntent (never undefined).
514	 * INVARIANT 5: Refunds always pass `reverse_transfer: true` AND `refund_application_fee: true`.
515	 * INVARIANT 6: `subscriptions` and `stripe_charges` are webhook-only writes from app code.
516	 * INVARIANT 7: Dodo (L1) and Stripe (L2) abstractions never share a module.
517	 * INVARIANT 8: Banker's rounding when computing splits to avoid systematic bias.
518	 */
519

