/**
 * Stripe webhook event processor — extracted helper.
 *
 * Called by:
 *   1. app/api/webhooks/stripe/route.ts — after signature verification
 *   2. workers/jobs/webhook-replay.ts   — bypasses sig verification for trusted internal replays
 *
 * This function is the ONLY source of truth for post-verification Stripe event dispatch.
 * Adding a new event type: add a case here only, not in the route.
 *
 * INVARIANT 7: Dodo (L1) and Stripe (L2) abstractions never share a module.
 */

import type Stripe from 'stripe'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import {
  RPC,
  type StripeConnectedAccountUpdateFromWebhookArgs,
  type StripeChargeUpdateStatusFromWebhookArgs,
  type StripeDisputeRecordArgs,
  type StripeDisputeUpdateStatusFromWebhookArgs,
  type ConnectedAccountOnboardingStatus,
  type Currency,
  type StripeChargeStatus,
  type StripeDisputeStatus,
  cents,
} from '@/lib/payments/contracts'

// Sprint 13: stripe_connected_account_*, stripe_charge_*, stripe_dispute_* RPCs and
// stripe_charges table are not yet reflected in generated lib/supabase/types.ts.
// Run `pnpm db:types` after Dato's migration lands to remove these casts (§S13.3).
type UntypedRpc = (
  fn: string,
  args: Record<string, unknown>,
) => Promise<{ data: unknown; error: { message: string } | null }>

type UntypedFrom = (table: string) => {
  select: (cols: string) => {
    eq: (col: string, val: string) => {
      maybeSingle: () => Promise<{ data: Record<string, string> | null; error: unknown }>
    }
  }
}

type SupabaseServiceClient = ReturnType<typeof createServiceRoleClient>

/**
 * Dispatch a verified Stripe event to the appropriate handler.
 *
 * @param event   - Fully parsed and verified Stripe.Event (signature already checked).
 * @param supabase - Service-role client. Bypasses RLS. Caller must supply this.
 * @throws         - On RPC failure. Caller is responsible for error logging + retry.
 */
export async function processStripeEvent(
  event: Stripe.Event,
  supabase: SupabaseServiceClient,
): Promise<void> {
  logger.info({ type: event.type, eventId: event.id }, 'stripe: processing event')

  switch (event.type) {
    case 'account.updated':
      await handleAccountUpdated(event.data.object as Stripe.Account, supabase)
      break

    case 'payment_intent.succeeded':
      await handlePaymentIntentStatusChange(
        event.data.object as Stripe.PaymentIntent,
        'succeeded',
        supabase,
      )
      break

    case 'payment_intent.payment_failed':
      await handlePaymentIntentStatusChange(
        event.data.object as Stripe.PaymentIntent,
        'requires_payment_method',
        supabase,
      )
      break

    case 'payment_intent.canceled':
      await handlePaymentIntentStatusChange(
        event.data.object as Stripe.PaymentIntent,
        'canceled',
        supabase,
      )
      break

    case 'charge.dispute.created':
      await handleDisputeCreated(event.data.object as Stripe.Dispute, supabase)
      break

    case 'charge.dispute.closed':
      await handleDisputeClosed(event.data.object as Stripe.Dispute, supabase)
      break

    default:
      logger.info({ type: event.type, eventId: event.id }, 'stripe: event recorded, not processed')
  }
}

// ---------------------------------------------------------------------------
// account.updated
// ---------------------------------------------------------------------------

async function handleAccountUpdated(
  account: Stripe.Account,
  supabase: SupabaseServiceClient,
): Promise<void> {
  const onboardingStatus = deriveOnboardingStatus(account)
  const capabilities = account.capabilities ?? {}
  const restrictedReason = account.requirements?.disabled_reason ?? null

  const currentDeadline = account.requirements?.current_deadline
  const requirementsDueBy = currentDeadline
    ? new Date(currentDeadline * 1_000).toISOString()
    : null

  const args: StripeConnectedAccountUpdateFromWebhookArgs = {
    accountId: account.id,
    onboardingStatus,
    capabilities: {
      charges_enabled: account.charges_enabled ?? false,
      payouts_enabled: account.payouts_enabled ?? false,
      transfers: (capabilities as Record<string, string>)['transfers'] === 'active',
      tax_reporting_us_1099_nec:
        (capabilities as Record<string, string>)['tax_reporting_us_1099_nec'] === 'active',
    },
    country: account.country ?? 'US',
    defaultCurrency: (account.default_currency ?? 'usd') as Currency,
    restrictedReason,
    requirementsDueBy,
  }

  const rpc = supabase.rpc.bind(supabase) as unknown as UntypedRpc
  const { data, error } = await rpc(RPC.STRIPE_CONNECTED_ACCOUNT_UPDATE_FROM_WEBHOOK, {
    p_account_id: args.accountId,
    p_onboarding_status: args.onboardingStatus,
    p_capabilities: args.capabilities,
    p_country: args.country,
    p_default_currency: args.defaultCurrency,
    p_restricted_reason: args.restrictedReason,
    p_requirements_due_by: args.requirementsDueBy,
  })

  if (error) {
    logger.error({ err: error, accountId: account.id }, 'stripe: account.updated RPC failed')
    throw error
  }

  logger.info({ accountId: account.id, result: data }, 'stripe: account.updated processed')
}

function deriveOnboardingStatus(account: Stripe.Account): ConnectedAccountOnboardingStatus {
  if (account.charges_enabled && account.payouts_enabled) return 'active'

  const disabledReason = account.requirements?.disabled_reason
  if (disabledReason) return 'restricted'

  const errors = account.requirements?.errors ?? []
  if (errors.length > 0) return 'restricted'

  return 'pending'
}

// ---------------------------------------------------------------------------
// payment_intent.succeeded / payment_failed / canceled
// ---------------------------------------------------------------------------

async function handlePaymentIntentStatusChange(
  pi: Stripe.PaymentIntent,
  status: StripeChargeStatus,
  supabase: SupabaseServiceClient,
): Promise<void> {
  const latestCharge = pi.latest_charge
  const chargeId = typeof latestCharge === 'string' ? latestCharge : (latestCharge?.id ?? null)

  const args: StripeChargeUpdateStatusFromWebhookArgs = {
    paymentIntentId: pi.id,
    status,
    chargeId,
    transferId: null,
    applicationFeeId: null,
  }

  const rpc = supabase.rpc.bind(supabase) as unknown as UntypedRpc
  const { data, error } = await rpc(RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK, {
    p_payment_intent_id: args.paymentIntentId,
    p_status: args.status,
    p_charge_id: args.chargeId,
    p_transfer_id: args.transferId,
    p_application_fee_id: args.applicationFeeId,
  })

  if (error) {
    logger.error({ err: error, piId: pi.id, status }, 'stripe: charge status update RPC failed')
    throw error
  }

  logger.info({ piId: pi.id, status, result: data }, 'stripe: payment_intent status updated')
}

// ---------------------------------------------------------------------------
// charge.dispute.created
// ---------------------------------------------------------------------------

async function handleDisputeCreated(
  dispute: Stripe.Dispute,
  supabase: SupabaseServiceClient,
): Promise<void> {
  const chargeId = typeof dispute.charge === 'string' ? dispute.charge : dispute.charge?.id
  if (!chargeId) {
    logger.warn({ disputeId: dispute.id }, 'stripe: dispute missing charge id — skipping')
    return
  }

  const studioId = await resolveStudioIdFromCharge(chargeId, supabase)
  if (!studioId) {
    logger.warn({ disputeId: dispute.id, chargeId }, 'stripe: could not resolve studio_id for dispute')
    return
  }

  const evidenceDueBy = dispute.evidence_details?.due_by
    ? new Date(dispute.evidence_details.due_by * 1_000).toISOString()
    : new Date(Date.now() + 7 * 24 * 60 * 60 * 1_000).toISOString()

  const args: StripeDisputeRecordArgs = {
    studioId,
    disputeId: dispute.id,
    chargeId,
    reason: dispute.reason,
    status: dispute.status as StripeDisputeStatus,
    amountCents: cents(dispute.amount),
    currency: (dispute.currency ?? 'usd') as Currency,
    evidenceDueBy,
  }

  const rpc = supabase.rpc.bind(supabase) as unknown as UntypedRpc
  const { data, error } = await rpc(RPC.STRIPE_DISPUTE_RECORD, {
    p_studio_id: args.studioId,
    p_dispute_id: args.disputeId,
    p_charge_id: args.chargeId,
    p_reason: args.reason,
    p_status: args.status,
    p_amount_cents: args.amountCents,
    p_currency: args.currency,
    p_evidence_due_by: args.evidenceDueBy,
  })

  if (error) {
    logger.error({ err: error, disputeId: dispute.id }, 'stripe: dispute.created RPC failed')
    throw error
  }

  logger.info({ disputeId: dispute.id, studioId, result: data }, 'stripe: dispute recorded')
}

// ---------------------------------------------------------------------------
// charge.dispute.closed
// ---------------------------------------------------------------------------

async function handleDisputeClosed(
  dispute: Stripe.Dispute,
  supabase: SupabaseServiceClient,
): Promise<void> {
  const resolvedAmountCents =
    dispute.status === 'lost' ? cents(dispute.amount) : null

  const resolvedAt = new Date().toISOString()

  const args: StripeDisputeUpdateStatusFromWebhookArgs = {
    disputeId: dispute.id,
    status: dispute.status as StripeDisputeStatus,
    resolvedAt,
    resolvedAmountCents,
  }

  const rpc = supabase.rpc.bind(supabase) as unknown as UntypedRpc
  const { data, error } = await rpc(RPC.STRIPE_DISPUTE_UPDATE_STATUS_FROM_WEBHOOK, {
    p_dispute_id: args.disputeId,
    p_status: args.status,
    p_resolved_at: args.resolvedAt,
    p_resolved_amount_cents: args.resolvedAmountCents,
  })

  if (error) {
    logger.error({ err: error, disputeId: dispute.id }, 'stripe: dispute.closed RPC failed')
    throw error
  }

  logger.info({ disputeId: dispute.id, status: dispute.status, result: data }, 'stripe: dispute closed')
}

// ---------------------------------------------------------------------------
// Lookup helpers
// ---------------------------------------------------------------------------

async function resolveStudioIdFromCharge(
  chargeId: string,
  supabase: SupabaseServiceClient,
): Promise<string | null> {
  // stripe_charges table is a Sprint 13 addition — not yet in generated types.ts.
  const from = supabase.from.bind(supabase) as unknown as UntypedFrom
  const { data } = await from('stripe_charges')
    .select('studio_id')
    .eq('charge_id', chargeId)
    .maybeSingle()
  return data?.['studio_id'] ?? null
}

/**
 * Dodo Payments webhook event processor — extracted helper.
 *
 * Called by:
 *   1. app/api/webhooks/dodo/route.ts — after signature verification
 *   2. workers/jobs/webhook-replay.ts — bypasses sig verification for trusted internal replays
 *
 * This function is the ONLY source of truth for post-verification Dodo event dispatch.
 * Adding a new event type: add a case here only, not in the route.
 *
 * INVARIANT 7: Dodo (L1) and Stripe (L2) abstractions never share a module.
 */

import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { resolveProduct } from '@/lib/dodo/products'
import { enqueueJob } from '@/lib/queue'
import type {
  DodoWebhookEvent,
  SubscriptionCreatedSchema,
  SubscriptionCancelledSchema,
  SubscriptionTrialEndedSchema,
  InvoiceSchema,
  PaymentSchema,
  CustomerUpdatedSchema,
} from '@/lib/dodo/webhook'
import type { Json } from '@/lib/supabase/types'
import type { z } from 'zod'

type SupabaseServiceClient = ReturnType<typeof createServiceRoleClient>

/**
 * Dispatch a verified Dodo event to the appropriate handler.
 *
 * @param event   - Fully parsed and type-narrowed DodoWebhookEvent (Zod-validated).
 * @param eventId - The webhook-id header value (idempotency key / log correlation).
 * @param supabase - Service-role client. Bypasses RLS. Caller must supply this.
 * @throws         - On DB failure. Caller is responsible for error logging + retry.
 */
export async function processDodoEvent(
  event: DodoWebhookEvent,
  eventId: string,
  supabase: SupabaseServiceClient,
): Promise<void> {
  logger.info({ type: event.type, eventId }, 'dodo: processing event')

  switch (event.type) {
    case 'subscription.created':
    case 'subscription.updated':
      await handleSubscriptionUpsert(event.data, supabase)
      break
    case 'subscription.cancelled':
      await handleSubscriptionCancelled(event.data, supabase)
      break
    case 'subscription.trial_ended':
      await handleTrialEnded(event.data, supabase)
      break
    case 'invoice.created':
      await handleInvoiceCreated(event.data, supabase)
      break
    case 'invoice.paid':
      await handleInvoicePaid(event.data, supabase)
      break
    case 'invoice.payment_failed':
      await handleInvoicePaymentFailed(event.data, supabase)
      break
    case 'payment.succeeded':
      await handlePaymentSucceeded(event.data, supabase)
      break
    case 'payment.failed':
      await handlePaymentFailed(event.data, supabase)
      break
    case 'payment.refunded':
      await handlePaymentRefunded(event.data, supabase)
      break
    case 'customer.updated':
      await handleCustomerUpdated(event.data, supabase)
      break
  }
}

// ---------------------------------------------------------------------------
// subscription.created / subscription.updated
// ---------------------------------------------------------------------------

async function handleSubscriptionUpsert(
  data: z.infer<typeof SubscriptionCreatedSchema>,
  supabase: SupabaseServiceClient,
) {
  const studioId = data.metadata?.['studioId']
  if (!studioId) {
    logger.warn({ subscriptionId: data.id }, 'dodo: subscription event missing studioId metadata')
    return
  }

  const resolved = resolveProduct(data.product_id ?? '')
  const planTier = resolved?.tier ?? 'solo'
  const billingCycle = resolved?.billingCycle ?? 'monthly'

  const { error } = await supabase.from('subscriptions').upsert(
    {
      studio_id: studioId,
      dodo_subscription_id: data.id,
      dodo_customer_id: data.customer_id ?? null,
      plan_tier: planTier,
      billing_cycle: billingCycle,
      status: mapSubscriptionStatus(data.status),
      trial_start: data.trial_start ?? null,
      trial_end: data.trial_end ?? null,
      current_period_start: data.current_period_start ?? null,
      current_period_end: data.current_period_end ?? null,
      price_cents: data.amount ?? 0,
      currency: data.currency ?? 'USD',
      updated_at: new Date().toISOString(),
    },
    { onConflict: 'studio_id' },
  )

  if (error) throw error

  await logAuditAction(
    null,
    'subscription.upsert',
    { type: 'studio', id: studioId },
    { planTier, status: data.status },
    studioId,
  )
}

// ---------------------------------------------------------------------------
// subscription.cancelled
// ---------------------------------------------------------------------------

async function handleSubscriptionCancelled(
  data: z.infer<typeof SubscriptionCancelledSchema>,
  supabase: SupabaseServiceClient,
) {
  const studioId = data.metadata?.['studioId']
  if (!studioId) return

  const { error } = await supabase
    .from('subscriptions')
    .update({
      status: 'canceled',
      cancelled_at: data.cancelled_at ?? new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq('dodo_subscription_id', data.id)

  if (error) throw error
  await logAuditAction(
    null,
    'subscription.cancelled',
    { type: 'studio', id: studioId },
    null,
    studioId,
  )
}

// ---------------------------------------------------------------------------
// subscription.trial_ended
// ---------------------------------------------------------------------------

async function handleTrialEnded(
  data: z.infer<typeof SubscriptionTrialEndedSchema>,
  supabase: SupabaseServiceClient,
) {
  const newStatus = data.status === 'past_due' ? 'past_due' : 'active'
  const { error } = await supabase
    .from('subscriptions')
    .update({ status: newStatus, updated_at: new Date().toISOString() })
    .eq('dodo_subscription_id', data.id)

  if (error) throw error
}

// ---------------------------------------------------------------------------
// invoice.created
// ---------------------------------------------------------------------------

async function handleInvoiceCreated(
  data: z.infer<typeof InvoiceSchema>,
  supabase: SupabaseServiceClient,
) {
  const studioId = await resolveStudioIdFromSubscription(
    data.subscription_id ?? null,
    data.customer_id ?? null,
    data.metadata,
    supabase,
  )
  if (!studioId) return

  await supabase.from('invoices').insert({
    studio_id: studioId,
    dodo_invoice_id: data.id,
    subscription_id: await resolveSubscriptionRowId(data.subscription_id ?? null, supabase),
    amount_cents: data.amount ?? 0,
    tax_cents: data.tax ?? 0,
    currency: data.currency ?? 'USD',
    status: 'open',
    period_start: data.period_start ?? null,
    period_end: data.period_end ?? null,
    due_date: data.due_date ?? null,
    line_items: (data.line_items ?? []) as unknown as Json,
    metadata: {},
  })
}

// ---------------------------------------------------------------------------
// invoice.paid
// ---------------------------------------------------------------------------

async function handleInvoicePaid(
  data: z.infer<typeof InvoiceSchema>,
  supabase: SupabaseServiceClient,
) {
  const { error } = await supabase
    .from('invoices')
    .update({
      status: 'paid',
      dodo_payment_id: data.payment_id ?? null,
      paid_at: data.paid_at ?? new Date().toISOString(),
      pdf_url: data.pdf_url ?? null,
      hosted_url: data.hosted_url ?? null,
      updated_at: new Date().toISOString(),
    })
    .eq('dodo_invoice_id', data.id)

  if (error) throw error

  const studioId = await resolveStudioIdFromSubscription(
    data.subscription_id ?? null,
    data.customer_id ?? null,
    data.metadata,
    supabase,
  )
  if (studioId) {
    const { data: studioRow } = await supabase.from('studios').select('name').eq('id', studioId).single()
    const ownerEmail = await resolveOwnerEmail(studioId, supabase)
    if (ownerEmail) {
      try {
        await enqueueJob('send-email', {
          to: ownerEmail,
          template: 'invoice_paid',
          data: {
            studioName: studioRow?.name ?? '',
            invoiceId: data.id,
            amountCents: data.amount ?? 0,
            currency: data.currency ?? 'USD',
            paidAt: data.paid_at ?? '',
            pdfUrl: data.pdf_url ?? null,
            studioId,
          } as Record<string, unknown>,
        })
      } catch (e) {
        logger.warn({ err: e }, 'dodo: failed to enqueue invoice_paid email')
      }
    }
  }
}

// ---------------------------------------------------------------------------
// invoice.payment_failed
// ---------------------------------------------------------------------------

async function handleInvoicePaymentFailed(
  data: z.infer<typeof InvoiceSchema>,
  supabase: SupabaseServiceClient,
) {
  await supabase
    .from('invoices')
    .update({ status: 'open', updated_at: new Date().toISOString() })
    .eq('dodo_invoice_id', data.id)

  if (data.subscription_id) {
    await supabase
      .from('subscriptions')
      .update({ status: 'past_due', updated_at: new Date().toISOString() })
      .eq('dodo_subscription_id', data.subscription_id)
  }
}

// ---------------------------------------------------------------------------
// payment.succeeded
// ---------------------------------------------------------------------------

async function handlePaymentSucceeded(
  data: z.infer<typeof PaymentSchema>,
  supabase: SupabaseServiceClient,
) {
  if (data.metadata?.['type'] === 'project_deposit') {
    await handleProjectDepositSucceeded(data, supabase)
    return
  }

  const studioId =
    data.metadata?.['studioId'] ??
    (await resolveStudioIdFromCustomer(data.customer_id ?? null, supabase))
  if (!studioId) {
    logger.warn({ paymentId: data.id }, 'dodo: payment.succeeded missing studioId')
    return
  }

  const paymentType = (
    data.metadata?.['kind'] === 'deposit'
      ? 'deposit'
      : data.metadata?.['kind'] === 'balance'
        ? 'balance'
        : 'subscription'
  ) satisfies 'deposit' | 'balance' | 'subscription'

  await supabase.from('payments').upsert(
    {
      studio_id: studioId,
      dodo_payment_id: data.id,
      dodo_checkout_id: data.checkout_id ?? null,
      invoice_id: await resolveInvoiceRowId(data.invoice_id ?? null, supabase),
      type: paymentType,
      amount_cents: data.amount,
      currency: data.currency ?? 'USD',
      status: 'succeeded',
      succeeded_at: data.succeeded_at ?? new Date().toISOString(),
      metadata: data.metadata ?? {},
    },
    { onConflict: 'dodo_payment_id' },
  )

  if (data.metadata?.['kind'] === 'deposit') {
    const bookingToken = data.metadata?.['booking_token']
    if (bookingToken) {
      const { data: booking } = await supabase
        .from('bookings')
        .select('id, studio_id, client_id, service_id')
        .eq('booking_token', bookingToken)
        .single()

      if (booking) {
        if (booking.studio_id !== studioId) {
          logger.error(
            { bookingToken, metadataStudio: studioId, bookingStudio: booking.studio_id },
            'dodo: studio_id mismatch on deposit — ignoring',
          )
          return
        }

        await supabase
          .from('bookings')
          .update({
            deposit_paid: true,
            deposit_paid_at: data.succeeded_at ?? new Date().toISOString(),
            deposit_payment_id: data.id,
          })
          .eq('booking_token', bookingToken)

        await supabase
          .from('payments')
          .update({ booking_id: booking.id, client_id: booking.client_id })
          .eq('dodo_payment_id', data.id)

        const { data: clientRow } = await supabase
          .from('clients')
          .select('email, first_name')
          .eq('id', booking.client_id)
          .single()

        if (clientRow?.email) {
          const { data: serviceRow } = booking.service_id
            ? await supabase
                .from('services')
                .select('name, deposit_cents')
                .eq('id', booking.service_id)
                .single()
            : { data: null }
          const { data: bookingFull } = await supabase
            .from('bookings')
            .select('scheduled_at')
            .eq('booking_token', bookingToken)
            .single()
          const { data: studioRow } = await supabase
            .from('studios')
            .select('name')
            .eq('id', studioId)
            .single()

          try {
            await enqueueJob('send-email', {
              to: clientRow.email,
              template: 'deposit_received',
              data: {
                clientName: clientRow.first_name,
                serviceName: serviceRow?.name ?? '',
                scheduledAt: bookingFull?.scheduled_at
                  ? new Date(bookingFull.scheduled_at).toLocaleString('en-US', {
                      month: 'short',
                      day: 'numeric',
                      hour: '2-digit',
                      minute: '2-digit',
                    })
                  : '',
                depositCents: serviceRow?.deposit_cents ?? data.amount,
                studioName: studioRow?.name ?? '',
                bookingToken,
                studioId,
                clientId: booking.client_id,
                bookingId: booking.id,
              } as Record<string, unknown>,
            })
          } catch (e) {
            logger.warn({ err: e }, 'dodo: failed to enqueue deposit_received email')
          }
        }
      }
    }
  }

  if (data.metadata?.['kind'] === 'balance') {
    const bookingId = data.metadata?.['booking_id']
    if (bookingId) {
      await supabase
        .from('bookings')
        .update({
          balance_paid: true,
          balance_paid_at: data.succeeded_at ?? new Date().toISOString(),
          balance_payment_id: data.id,
        })
        .eq('id', bookingId)

      await supabase
        .from('payments')
        .update({ booking_id: bookingId })
        .eq('dodo_payment_id', data.id)
    }
  }
}

// ---------------------------------------------------------------------------
// payment.failed
// ---------------------------------------------------------------------------

async function handlePaymentFailed(
  data: z.infer<typeof PaymentSchema>,
  supabase: SupabaseServiceClient,
) {
  const studioId =
    data.metadata?.['studioId'] ??
    (await resolveStudioIdFromCustomer(data.customer_id ?? null, supabase))
  if (!studioId) return

  await supabase.from('payments').upsert(
    {
      studio_id: studioId,
      dodo_payment_id: data.id,
      dodo_checkout_id: data.checkout_id ?? null,
      type: 'subscription',
      amount_cents: data.amount,
      currency: data.currency ?? 'USD',
      status: 'failed',
      failure_code: data.failure_code ?? null,
      failure_message: data.failure_message ?? null,
      metadata: data.metadata ?? {},
    },
    { onConflict: 'dodo_payment_id' },
  )

  const ownerEmail = await resolveOwnerEmail(studioId, supabase)
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  if (ownerEmail) {
    const { data: studioRow } = await supabase.from('studios').select('name').eq('id', studioId).single()
    try {
      await enqueueJob('send-email', {
        to: ownerEmail,
        template: 'payment_failed',
        data: {
          studioName: studioRow?.name ?? '',
          amountCents: data.amount,
          currency: data.currency ?? 'USD',
          retryUrl: `${appUrl}/settings/billing`,
          failureReason: data.failure_message ?? null,
          studioId,
        } as Record<string, unknown>,
      })
    } catch (e) {
      logger.warn({ err: e }, 'dodo: failed to enqueue payment_failed email')
    }
  }
}

// ---------------------------------------------------------------------------
// payment.refunded
// ---------------------------------------------------------------------------

async function handlePaymentRefunded(
  data: z.infer<typeof PaymentSchema>,
  supabase: SupabaseServiceClient,
) {
  if (data.metadata?.['type'] === 'project_deposit') {
    await handleProjectDepositRefunded(data, supabase)
    return
  }

  await supabase
    .from('payments')
    .update({
      status: 'refunded',
      refund_amount_cents: data.refund_amount ?? 0,
      refunded_at: data.refunded_at ?? new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq('dodo_payment_id', data.id)

  const { data: paymentRow } = await supabase
    .from('payments')
    .select('id')
    .eq('dodo_payment_id', data.id)
    .maybeSingle()

  if (!paymentRow) {
    logger.error({ dodoPaymentId: data.id }, 'dodo: payment.refunded — no matching payment row')
    return
  }

  const { data: updatedRows } = await supabase
    .from('refund_requests')
    .update({
      status: 'processed',
      dodo_refund_id: data.refund_id ?? null,
      processed_at: data.refunded_at ?? new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq('payment_id', paymentRow.id)
    .in('status', ['approved', 'pending'])
    .select('id')

  if (!updatedRows || updatedRows.length === 0) {
    logger.warn(
      { dodoPaymentId: data.id, internalPaymentId: paymentRow.id },
      'dodo: payment.refunded — no refund_request row matched',
    )
  }
}

// ---------------------------------------------------------------------------
// customer.updated
// ---------------------------------------------------------------------------

async function handleCustomerUpdated(
  data: z.infer<typeof CustomerUpdatedSchema>,
  supabase: SupabaseServiceClient,
) {
  const studioId = data.metadata?.['studioId']
  if (!studioId) return

  await supabase
    .from('subscriptions')
    .update({
      dodo_customer_id: data.id,
      updated_at: new Date().toISOString(),
    })
    .eq('studio_id', studioId)
}

// ---------------------------------------------------------------------------
// Project deposit helpers (private — payment.succeeded / payment.refunded paths)
// ---------------------------------------------------------------------------

async function handleProjectDepositSucceeded(
  data: z.infer<typeof PaymentSchema>,
  supabase: SupabaseServiceClient,
): Promise<void> {
  const projectId = data.metadata?.['project_id']
  if (!projectId) {
    logger.warn({ paymentId: data.id }, 'dodo: project_deposit payment.succeeded missing project_id metadata')
    return
  }

  const amountCents = data.amount
  if (!amountCents || amountCents <= 0) {
    logger.warn({ paymentId: data.id, projectId }, 'dodo: project_deposit payment.succeeded zero/missing amount')
    return
  }

  const { data: existingTx } = await supabase
    .from('project_deposit_transactions' as 'projects')
    .select('id' as never)
    .eq('external_id' as never, data.id)
    .eq('project_id' as never, projectId)
    .maybeSingle()

  if (existingTx) {
    logger.info({ paymentId: data.id, projectId }, 'dodo: project_deposit already recorded — skipping duplicate')
    return
  }

  type RpcResult = { data: string | null; error: { message: string } | null }
  const rpcFn = supabase.rpc.bind(supabase) as unknown as (
    fn: string,
    args: Record<string, unknown>,
  ) => Promise<RpcResult>

  const { error: rpcErr } = await rpcFn('record_project_deposit', {
    p_project_id: projectId,
    p_amount_cents: amountCents,
    p_method: 'stripe',
    p_external_id: data.id,
    p_note: 'Paid via checkout link',
  })

  if (rpcErr) {
    logger.error({ rpcErr, paymentId: data.id, projectId }, 'dodo: record_project_deposit RPC failed')
    throw new Error(`record_project_deposit failed: ${rpcErr.message}`)
  }

  logger.info({ paymentId: data.id, projectId, amountCents }, 'dodo: project_deposit recorded via webhook')
}

async function handleProjectDepositRefunded(
  data: z.infer<typeof PaymentSchema>,
  supabase: SupabaseServiceClient,
): Promise<void> {
  const projectId = data.metadata?.['project_id']
  if (!projectId) return

  const refundCents = data.refund_amount ?? data.amount
  if (!refundCents || refundCents <= 0) return

  if (data.refund_id) {
    const { data: existingRefund } = await supabase
      .from('project_deposit_transactions' as 'projects')
      .select('id' as never)
      .eq('external_id' as never, data.refund_id)
      .eq('project_id' as never, projectId)
      .eq('type' as never, 'refunded')
      .maybeSingle()

    if (existingRefund) {
      logger.info({ refundId: data.refund_id, projectId }, 'dodo: project_deposit refund already recorded — skipping')
      return
    }
  }

  type RpcResult = { data: string | null; error: { message: string } | null }
  const rpcFn = supabase.rpc.bind(supabase) as unknown as (
    fn: string,
    args: Record<string, unknown>,
  ) => Promise<RpcResult>

  const { error: rpcErr } = await rpcFn('refund_project_deposit', {
    p_project_id: projectId,
    p_amount_cents: refundCents,
    p_external_refund_id: data.refund_id ?? null,
    p_note: 'Refund via Dodo',
  })

  if (rpcErr) {
    logger.error({ rpcErr, paymentId: data.id, projectId }, 'dodo: refund_project_deposit RPC failed')
    throw new Error(`refund_project_deposit failed: ${rpcErr.message}`)
  }

  logger.info({ refundId: data.refund_id, projectId, refundCents }, 'dodo: project_deposit refund recorded via webhook')
}

// ---------------------------------------------------------------------------
// Lookup helpers (private)
// ---------------------------------------------------------------------------

function mapSubscriptionStatus(
  status: string,
): 'trialing' | 'active' | 'past_due' | 'canceled' | 'unpaid' {
  switch (status) {
    case 'trialing':
      return 'trialing'
    case 'active':
      return 'active'
    case 'past_due':
      return 'past_due'
    case 'canceled':
    case 'cancelled':
      return 'canceled'
    case 'unpaid':
      return 'unpaid'
    default:
      return 'active'
  }
}

async function resolveStudioIdFromSubscription(
  dodoSubId: string | null,
  customerId: string | null,
  metadata: Record<string, string> | undefined,
  supabase: SupabaseServiceClient,
): Promise<string | null> {
  if (metadata?.['studioId']) return metadata['studioId']

  if (dodoSubId) {
    const { data } = await supabase
      .from('subscriptions')
      .select('studio_id')
      .eq('dodo_subscription_id', dodoSubId)
      .maybeSingle()
    if (data) return data.studio_id
  }

  if (customerId) {
    return resolveStudioIdFromCustomer(customerId, supabase)
  }

  return null
}

async function resolveStudioIdFromCustomer(
  customerId: string | null,
  supabase: SupabaseServiceClient,
): Promise<string | null> {
  if (!customerId) return null
  const { data } = await supabase
    .from('subscriptions')
    .select('studio_id')
    .eq('dodo_customer_id', customerId)
    .maybeSingle()
  return data?.studio_id ?? null
}

async function resolveSubscriptionRowId(
  dodoSubId: string | null,
  supabase: SupabaseServiceClient,
): Promise<string | null> {
  if (!dodoSubId) return null
  const { data } = await supabase
    .from('subscriptions')
    .select('id')
    .eq('dodo_subscription_id', dodoSubId)
    .maybeSingle()
  return data?.id ?? null
}

async function resolveInvoiceRowId(
  dodoInvoiceId: string | null,
  supabase: SupabaseServiceClient,
): Promise<string | null> {
  if (!dodoInvoiceId) return null
  const { data } = await supabase
    .from('invoices')
    .select('id')
    .eq('dodo_invoice_id', dodoInvoiceId)
    .maybeSingle()
  return data?.id ?? null
}

// C3: Two-query resolution — studio_members.user_id FKs to auth.users, not profiles.
async function resolveOwnerEmail(
  studioId: string,
  supabase: SupabaseServiceClient,
): Promise<string | null> {
  const { data: member } = await supabase
    .from('studio_members')
    .select('user_id')
    .eq('studio_id', studioId)
    .eq('role', 'owner')
    .limit(1)
    .maybeSingle()

  if (!member?.user_id) return null

  const { data: profile } = await supabase
    .from('profiles')
    .select('email')
    .eq('id', member.user_id)
    .maybeSingle()

  return profile?.email ?? null
}

import { type NextRequest, NextResponse } from 'next/server'
import type Stripe from 'stripe'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { verifyStripeWebhook } from '@/lib/stripe/webhook-verify'
import { insertWebhookEvent } from '@/lib/payments/webhook-events'
import { processStripeEvent } from '@/lib/payments/process-stripe-event'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { webhookRatelimit } from '@/lib/rate-limit'

export const dynamic = 'force-dynamic'

/**
 * Stripe webhook handler — Sprint 13 Stripe Connect Express.
 *
 * Security order (must not be reordered):
 *  1. STRIPE_WEBHOOK_SECRET presence check
 *  2. IP-based rate limit (webhookRatelimit)
 *  3. Stripe signature verification via stripe.webhooks.constructEvent (5-min tolerance)
 *  4. Idempotency: insertWebhookEvent RPC (INSERT … ON CONFLICT DO NOTHING)
 *  5. Typed event dispatch via processStripeEvent (lib/payments/process-stripe-event.ts)
 *  6. RPC writes via service-role client (bypasses RLS)
 *
 * INVARIANT 3: insertWebhookEvent is always the first DB write.
 * INVARIANT 6: stripe_charges is webhook-only write from app code.
 * INVARIANT 7: Dodo and Stripe abstractions never share a module.
 *
 * Event processing logic lives entirely in lib/payments/process-stripe-event.ts.
 * The replay worker (workers/jobs/webhook-replay.ts) calls that helper directly,
 * bypassing this route's signature verification for trusted internal replays.
 */

export async function POST(req: NextRequest): Promise<NextResponse> {
  // Step 1: Guard — webhook secret must be configured
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET
  if (!webhookSecret) {
    logger.error('STRIPE_WEBHOOK_SECRET is not set — stripe webhook handler disabled')
    return NextResponse.json({ error: 'webhook not configured' }, { status: 503 })
  }

  // Step 2: Rate limit by IP
  const ip = getClientIp(req)
  const rl = await webhookRatelimit.limit(ip)
  if (!rl.success) {
    logger.warn({ ip }, 'stripe webhook: rate limit exceeded')
    return NextResponse.json({ error: 'too many requests' }, { status: 429 })
  }

  // Step 3: Read raw body — MUST be string; Stripe HMAC is over raw bytes
  const rawBody = await req.text()
  const sig = req.headers.get('stripe-signature')

  if (!sig) {
    logger.warn({ ip }, 'stripe webhook: missing stripe-signature header')
    return NextResponse.json({ error: 'missing stripe-signature' }, { status: 400 })
  }

  // Step 4: Verify signature — throws on invalid sig or stale timestamp (>5 min)
  let event: Stripe.Event
  try {
    event = verifyStripeWebhook(rawBody, sig, webhookSecret)
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'unknown'
    logger.warn({ msg, ip }, 'stripe webhook: signature verification failed')
    await logAuditAction(
      null,
      'webhook_signature_mismatch',
      null,
      { source: 'stripe', sig_present: true },
      null,
    )
    return NextResponse.json({ error: 'invalid signature' }, { status: 401 })
  }

  const supabase = createServiceRoleClient()

  // Step 5: Idempotency — first DB write, replay guard
  let insertResult: { inserted: boolean; id: string | null }
  try {
    insertResult = await insertWebhookEvent(supabase, {
      source: 'stripe',
      eventId: event.id,
      eventType: event.type,
      payload: event,
      signatureVerified: true,
    })
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'unknown'
    logger.error({ err: msg, eventId: event.id }, 'stripe webhook: failed to insert webhook_event row')
    return NextResponse.json({ error: 'internal error' }, { status: 500 })
  }

  if (!insertResult.inserted) {
    logger.info({ eventId: event.id }, 'stripe webhook: replay detected — skipping processing')
    return NextResponse.json({ received: true, replay: true })
  }

  // Step 6: Typed dispatch — all logic in process-stripe-event.ts
  try {
    await processStripeEvent(event, supabase)
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    logger.error({ err: msg, eventId: event.id, type: event.type }, 'stripe webhook: processing failed')
    return NextResponse.json({ error: 'processing failed' }, { status: 500 })
  }

  return NextResponse.json({ received: true, event_id: event.id, event_type: event.type })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import {
  verifyAndParseDodoWebhook,
  DodoWebhookEventSchema,
  DodoEnvelopeSchema,
} from '@/lib/dodo/webhook'
import { processDodoEvent } from '@/lib/payments/process-dodo-event'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import type { Json } from '@/lib/supabase/types'
import { RPC, type WebhookEventInsertArgs, type WebhookEventInsertResult } from '@/lib/payments/contracts'

export const dynamic = 'force-dynamic'

/**
 * Dodo Payments webhook handler.
 *
 * Security order (must not be reordered):
 *  1. standardwebhooks signature verification (whsec_ secret, 5-min timestamp tolerance)
 *  2. Zod parse envelope + event
 *  3. Idempotency via INSERT ... ON CONFLICT DO NOTHING on webhook_events(event_id)
 *  4. DB writes via service-role client (bypasses RLS)
 *
 * Event identity = webhook-id header (NOT a body field).
 * Dodo retries on non-2xx — always return 200 after recording the event row,
 * even on processing error (we log the error on the row for ops debugging).
 *
 * Event processing logic lives entirely in lib/payments/process-dodo-event.ts.
 * The replay worker (workers/jobs/webhook-replay.ts) calls that helper directly,
 * bypassing this route's signature verification for trusted internal replays.
 */

export async function POST(req: NextRequest) {
  const webhookKey = process.env.DODO_PAYMENTS_WEBHOOK_KEY
  if (!webhookKey) {
    logger.error('DODO_PAYMENTS_WEBHOOK_KEY is not set')
    return NextResponse.json({ error: 'webhook not configured' }, { status: 500 })
  }

  // Step 1: Read raw body before any parsing (must be string for signature verification)
  const rawBody = await req.text()

  // Step 2: Verify standardwebhooks signature — must come before any DB or parse work
  try {
    await verifyAndParseDodoWebhook(rawBody, req.headers, webhookKey)
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'unknown'
    logger.warn({ msg, ip: getClientIp(req) }, 'dodo webhook: signature verification failed')
    return NextResponse.json({ error: 'invalid signature' }, { status: 401 })
  }

  // Step 3: Parse envelope — event identity is in the webhook-id header
  // M2: use webhook-id header as idempotency key (not a body event_id field)
  const eventId = req.headers.get('webhook-id')
  if (!eventId) {
    logger.warn('dodo webhook: missing webhook-id header')
    return NextResponse.json({ error: 'missing webhook-id header' }, { status: 400 })
  }

  let rawParsed: unknown
  try {
    rawParsed = JSON.parse(rawBody)
  } catch {
    return NextResponse.json({ error: 'invalid json' }, { status: 400 })
  }

  const envelopeResult = DodoEnvelopeSchema.safeParse(rawParsed)
  if (!envelopeResult.success) {
    logger.warn({ errs: envelopeResult.error.format() }, 'dodo webhook: bad envelope shape')
    return NextResponse.json({ error: 'invalid envelope' }, { status: 400 })
  }

  const envelope = envelopeResult.data
  const supabase = createServiceRoleClient()

  // Step 4: Idempotency — atomic INSERT ON CONFLICT via RPC to prevent concurrent duplicate processing (M6)
  // INVARIANT 3: first write of every webhook handler is webhook_event_insert.
  const args: WebhookEventInsertArgs = {
    source: 'dodo',
    eventId: eventId,
    eventType: envelope.type ?? '',
    payload: rawParsed,
    signatureVerified: true,
  }

  // Cast required: webhook_event_insert RPC exists in SQL but not yet in generated types (Dato migration pending).
  const rpcFn = supabase.rpc.bind(supabase) as unknown as (
    fn: string,
    args: Record<string, unknown>,
  ) => Promise<{ data: unknown; error: { message: string; code?: string } | null }>

  const { data: rpcData, error: rpcError } = await rpcFn(RPC.WEBHOOK_EVENT_INSERT, {
    p_source: args.source,
    p_event_id: args.eventId,
    p_event_type: args.eventType,
    p_payload: args.payload as Json,
    p_signature_verified: args.signatureVerified,
  })

  if (rpcError) {
    logger.error({ err: rpcError, eventId }, 'dodo webhook: webhook_event_insert RPC failed')
    return NextResponse.json({ error: 'internal error' }, { status: 500 })
  }

  const result = rpcData as WebhookEventInsertResult
  if (!result.inserted) {
    logger.info({ source: 'dodo', event_id: args.eventId, replay: true }, 'webhook replay ignored')
    return NextResponse.json({ received: true, replay: true }, { status: 200 })
  }

  // Step 5: Parse typed event and process
  const eventResult = DodoWebhookEventSchema.safeParse({
    type: envelope.type,
    data: envelope.data,
  })

  if (!eventResult.success) {
    // Unknown event type — mark processed and return 200 so Dodo stops retrying
    logger.info({ type: envelope.type, eventId }, 'dodo webhook: unrecognized event type — ignoring')
    if (result.id) {
      await supabase
        .from('webhook_events')
        .update({ processed_at: new Date().toISOString() })
        .eq('id', result.id)
    }
    return NextResponse.json({ received: true, ignored: true })
  }

  const event = eventResult.data

  try {
    await processDodoEvent(event, eventId, supabase)

    if (result.id) {
      await supabase
        .from('webhook_events')
        .update({ processed_at: new Date().toISOString() })
        .eq('id', result.id)
    }

    return NextResponse.json({ received: true })
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err)
    logger.error({ err, eventId, type: event.type }, 'dodo webhook: processing failed')

    if (result.id) {
      await supabase
        .from('webhook_events')
        .update({ error: errMsg })
        .eq('id', result.id)
    }

    // Return 200 so Dodo doesn't retry — we've recorded the error for ops investigation
    return NextResponse.json({ received: true, error: errMsg })
  }
}

