input.content:
/**
 * webhook-replay BullMQ worker — dead-letter queue processor.
 *
 * Triggered when:
 *   1. Admin manually re-enqueues a failed event from POST /api/admin/webhooks/replay
 *   2. Reconciliation cron (S15+) detects drift and auto-enqueues
 *
 * Strategy: load the webhook_events row by (source, event_id), parse the stored
 * payload JSONB, then call the same process*Event helper used by the live route —
 * bypassing signature verification. This is safe because only service-role-authorized
 * internal callers (admin endpoint + future cron) can enqueue replay jobs.
 *
 * BullMQ config:
 *   attempts: 3
 *   backoff: { type: 'exponential', delay: 30_000 }  → ~30s, ~5min, ~1h
 *   After 3 failures: mark webhook_events.error = 'DEAD_LETTER'
 *
 * The job queue name is 'inkos-jobs' (shared queue, filtered by job.name).
 *
 * INVARIANT 7: Dodo (L1) and Stripe (L2) abstractions never share a module.
 * This worker imports process-stripe-event and process-dodo-event through
 * relative paths (workers cannot use @/ aliases).
 */

import { Worker } from 'bullmq'
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'
import { workerEnv } from '../lib/env.js'

// ---------------------------------------------------------------------------
// Relative imports to the extracted processors
// Workers NEVER import from next/* — use relative paths to lib/payments/*.
// These modules import from @/lib/* which is only valid in the Next.js app
// context. For workers we need plain relative resolution without the alias.
// SOLUTION: we dynamically resolve the actual process*Event functions at
// runtime by importing the compiled JS. Since ts-node / tsx resolves
// path aliases via tsconfig.json in the workers/ dir, we import via relative
// path from the project root.
//
// NOTE: workers/tsconfig.json must extend the root tsconfig and include
// "paths": { "@/*": ["../"] } or the workers use relative paths.
// Existing workers use ../lib/* (relative). We follow the same pattern here
// but the process-dodo-event and process-stripe-event helpers import from
// @/lib/... which is the Next.js app context. They cannot run directly in
// the worker process.
//
// CORRECT APPROACH per plan §5.3 simpler path: the replay worker calls the
// Supabase DB directly using the same logic — without importing the Next.js
// helpers. We inline the minimal dispatch needed: load row, call processEvent
// via direct DB RPC, update row. The heavy lifting (RPC calls) is the same
// code path; we avoid importing Next.js server modules.
// ---------------------------------------------------------------------------

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'webhook-replay'
const DEAD_LETTER_MARKER = 'DEAD_LETTER'

// ---------------------------------------------------------------------------
// Job payload type
// ---------------------------------------------------------------------------

interface WebhookReplayPayload {
  source: 'stripe' | 'dodo'
  event_id: string
  reason: 'admin_manual' | 'reconciliation_drift' | 'auto_retry'
  attempt: number
}

function isWebhookReplayPayload(data: unknown): data is WebhookReplayPayload {
  if (typeof data !== 'object' || data === null) return false
  const d = data as Record<string, unknown>
  return (
    (d['source'] === 'stripe' || d['source'] === 'dodo') &&
    typeof d['event_id'] === 'string' &&
    (d['reason'] === 'admin_manual' ||
      d['reason'] === 'reconciliation_drift' ||
      d['reason'] === 'auto_retry') &&
    typeof d['attempt'] === 'number'
  )
}

// ---------------------------------------------------------------------------
// Untyped RPC helper (mirrors the cast used in route handlers)
// webhook_event_insert + stripe/dodo RPCs not yet in generated types.ts
// ---------------------------------------------------------------------------

type UntypedRpcFn = (
  fn: string,
  args: Record<string, unknown>,
) => Promise<{ data: unknown; error: { message: string } | null }>

// ---------------------------------------------------------------------------
// Replay processor — the core logic
// ---------------------------------------------------------------------------

/**
 * Load the webhook_events row, parse the stored payload, call the correct
 * internal endpoint via service-role Supabase RPC.
 *
 * We do NOT import Next.js helpers here. Instead we directly call the same
 * RPCs that process-stripe-event.ts / process-dodo-event.ts call,
 * reconstructing only what the replay needs: the event type + payload.
 *
 * For Dodo: we call processDodoWebhookReplay — a direct RPC dispatch that
 * mirrors process-dodo-event's switch logic but runs inside the worker
 * process (no next/server dependency).
 *
 * For Stripe: same pattern.
 *
 * This is intentionally minimal. The full event processing logic lives in
 * the lib/payments/process-*.ts helpers which run inside the Next.js process.
 * The worker uses Supabase directly and calls the SAME RPCs those helpers call.
 */
async function processReplayJob(payload: WebhookReplayPayload): Promise<void> {
  const { source, event_id, reason, attempt } = payload
  const jobLog = logger.child({ source, event_id, reason, attempt })

  jobLog.info('webhook-replay: starting')

  // 1. Load the webhook_events row
  const { data: row, error: fetchErr } = await supabase
    .from('webhook_events')
    .select('id, event_type, payload, retry_count, error')
    .eq('source', source)
    .eq('event_id', event_id)
    .maybeSingle()

  if (fetchErr) {
    jobLog.error({ err: fetchErr }, 'webhook-replay: failed to load webhook_events row')
    throw new Error(`fetch failed: ${fetchErr.message}`)
  }

  if (!row) {
    jobLog.error('webhook-replay: webhook_events row not found — cannot replay')
    // Non-retriable: row must exist before replay is triggered
    throw new Error(`webhook_events row not found: source=${source} event_id=${event_id}`)
  }

  if (row.error === DEAD_LETTER_MARKER) {
    jobLog.warn('webhook-replay: row already dead-lettered — skipping')
    return
  }

  const rowId = row.id
  const currentRetryCount = row.retry_count ?? 0

  // 2. Dispatch to source-specific replay handler
  try {
    if (source === 'stripe') {
      await replayStripeEvent(row.payload, row.event_type, jobLog)
    } else {
      await replayDodoEvent(row.payload, event_id, jobLog)
    }
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err)
    jobLog.error({ err: errMsg }, 'webhook-replay: processing failed')

    // Update retry_count + error on the row so ops can inspect state
    await supabase
      .from('webhook_events')
      .update({
        retry_count: currentRetryCount + 1,
        error: errMsg,
      })
      .eq('id', rowId)

    // Re-throw so BullMQ applies its backoff + attempts logic
    throw err
  }

  // 3. Success — mark processed, clear error, increment retry_count
  await supabase
    .from('webhook_events')
    .update({
      processed_at: new Date().toISOString(),
      retry_count: currentRetryCount + 1,
      error: null,
    })
    .eq('id', rowId)

  jobLog.info('webhook-replay: completed successfully')
}

// ---------------------------------------------------------------------------
// Stripe replay dispatcher
// Calls the same RPCs as process-stripe-event.ts without Next.js imports.
// ---------------------------------------------------------------------------

async function replayStripeEvent(
  rawPayload: unknown,
  eventType: string,
  jobLog: ReturnType<typeof logger.child>,
): Promise<void> {
  jobLog.info({ eventType }, 'webhook-replay: replaying stripe event')

  // The payload stored in webhook_events is the full Stripe.Event object.
  // We dispatch to the appropriate RPC based on event type.
  // Only the event types handled in process-stripe-event.ts need cases here.
  const rpc = supabase.rpc.bind(supabase) as unknown as UntypedRpcFn

  // We re-use the stored payload object — Stripe.Event shape
  const event = rawPayload as Record<string, unknown>
  const dataObj = (event['data'] as Record<string, unknown>)?.['object'] as Record<string, unknown> ?? {}

  switch (eventType) {
    case 'account.updated': {
      const account = dataObj
      const onboardingStatus = deriveStripeOnboardingStatus(account)
      const capabilities = (account['capabilities'] as Record<string, string>) ?? {}
      const requirements = account['requirements'] as Record<string, unknown> | undefined
      const currentDeadline = requirements?.['current_deadline']
      const requirementsDueBy = typeof currentDeadline === 'number'
        ? new Date(currentDeadline * 1_000).toISOString()
        : null

      const { error } = await rpc('stripe_connected_account_update_from_webhook', {
        p_account_id: account['id'],
        p_onboarding_status: onboardingStatus,
        p_capabilities: {
          charges_enabled: account['charges_enabled'] === true,
          payouts_enabled: account['payouts_enabled'] === true,
          transfers: capabilities['transfers'] === 'active',
          tax_reporting_us_1099_nec: capabilities['tax_reporting_us_1099_nec'] === 'active',
        },
        p_country: account['country'] ?? 'US',
        p_default_currency: account['default_currency'] ?? 'usd',
        p_restricted_reason: requirements?.['disabled_reason'] ?? null,
        p_requirements_due_by: requirementsDueBy,
      })
      if (error) throw new Error(`account.updated RPC failed: ${error.message}`)
      break
    }

    case 'payment_intent.succeeded':
    case 'payment_intent.payment_failed':
    case 'payment_intent.canceled': {
      const pi = dataObj
      const latestCharge = pi['latest_charge']
      const chargeId =
        typeof latestCharge === 'string'
          ? latestCharge
          : (latestCharge as Record<string, string> | null)?.['id'] ?? null

      const statusMap: Record<string, string> = {
        'payment_intent.succeeded': 'succeeded',
        'payment_intent.payment_failed': 'requires_payment_method',
        'payment_intent.canceled': 'canceled',
      }

      const { error } = await rpc('stripe_charge_update_status_from_webhook', {
        p_payment_intent_id: pi['id'],
        p_status: statusMap[eventType],
        p_charge_id: chargeId,
        p_transfer_id: null,
        p_application_fee_id: null,
      })
      if (error) throw new Error(`${eventType} RPC failed: ${error.message}`)
      break
    }

    case 'charge.dispute.created': {
      const dispute = dataObj
      const chargeField = dispute['charge']
      const chargeId =
        typeof chargeField === 'string'
          ? chargeField
          : (chargeField as Record<string, string> | null)?.['id'] ?? null

      if (!chargeId) {
        jobLog.warn('webhook-replay: dispute missing charge id — skipping')
        return
      }

      // Resolve studio_id from stripe_charges
      const { data: chargeRow } = await supabase
        .from('stripe_charges' as 'projects')
        .select('studio_id' as never)
        .eq('charge_id' as never, chargeId)
        .maybeSingle()

      const studioId = (chargeRow as Record<string, string> | null)?.['studio_id'] ?? null
      if (!studioId) {
        jobLog.warn({ chargeId }, 'webhook-replay: could not resolve studio_id for dispute')
        return
      }

      const evidenceDetails = dispute['evidence_details'] as Record<string, number> | undefined
      const evidenceDueBy = evidenceDetails?.['due_by']
        ? new Date(evidenceDetails['due_by'] * 1_000).toISOString()
        : new Date(Date.now() + 7 * 24 * 60 * 60 * 1_000).toISOString()

      const amount = typeof dispute['amount'] === 'number' ? dispute['amount'] : 0
      const { error } = await rpc('stripe_dispute_record', {
        p_studio_id: studioId,
        p_dispute_id: dispute['id'],
        p_charge_id: chargeId,
        p_reason: dispute['reason'],
        p_status: dispute['status'],
        p_amount_cents: amount,
        p_currency: dispute['currency'] ?? 'usd',
        p_evidence_due_by: evidenceDueBy,
      })
      if (error) throw new Error(`dispute.created RPC failed: ${error.message}`)
      break
    }

    case 'charge.dispute.closed': {
      const dispute = dataObj
      const amount = typeof dispute['amount'] === 'number' ? dispute['amount'] : 0
      const resolvedAmountCents = dispute['status'] === 'lost' ? amount : null

      const { error } = await rpc('stripe_dispute_update_status_from_webhook', {
        p_dispute_id: dispute['id'],
        p_status: dispute['status'],
        p_resolved_at: new Date().toISOString(),
        p_resolved_amount_cents: resolvedAmountCents,
      })
      if (error) throw new Error(`dispute.closed RPC failed: ${error.message}`)
      break
    }

    default:
      jobLog.info({ eventType }, 'webhook-replay: stripe event type has no replay handler — marking done')
  }
}

function deriveStripeOnboardingStatus(
  account: Record<string, unknown>,
): 'active' | 'restricted' | 'pending' | 'rejected' {
  if (account['charges_enabled'] === true && account['payouts_enabled'] === true) return 'active'
  const requirements = account['requirements'] as Record<string, unknown> | undefined
  if (requirements?.['disabled_reason']) return 'restricted'
  const errors = requirements?.['errors']
  if (Array.isArray(errors) && errors.length > 0) return 'restricted'
  return 'pending'
}

// ---------------------------------------------------------------------------
// Dodo replay dispatcher
// Mirrors the event type switch in process-dodo-event.ts using direct Supabase
// calls — same DB operations, no Next.js server imports.
// ---------------------------------------------------------------------------

async function replayDodoEvent(
  rawPayload: unknown,
  eventId: string,
  jobLog: ReturnType<typeof logger.child>,
): Promise<void> {
  // Parse the stored envelope payload: { type, data }
  const envelope = rawPayload as Record<string, unknown>
  const eventType = envelope['type'] as string
  const data = (envelope['data'] as Record<string, unknown>) ?? {}

  jobLog.info({ eventType, eventId }, 'webhook-replay: replaying dodo event')

  // For Dodo replay: call the webhook endpoint internally.
  // The stored payload is the full request body that was originally received.
  // We POST it to our own internal endpoint with a trusted header instead of
  // re-running all the processing logic inline (which would require porting
  // every db helper to the worker context without @/ aliases).
  //
  // INTERNAL_BASE_URL must be set to the app's internal Railway private URL.
  // Falls back to NEXT_PUBLIC_APP_URL for local dev.
  const baseUrl =
    process.env.INTERNAL_BASE_URL ??
    process.env.NEXT_PUBLIC_APP_URL ??
    'http://localhost:3000'

  const replaySecret = process.env.WEBHOOK_REPLAY_INTERNAL_SECRET
  if (!replaySecret) {
    jobLog.error('WEBHOOK_REPLAY_INTERNAL_SECRET is not set — cannot authenticate internal replay call')
    throw new Error('WEBHOOK_REPLAY_INTERNAL_SECRET missing')
  }

  // POST the stored payload to a dedicated internal replay endpoint that:
  //   - verifies the X-Replay-Secret header (shared secret)
  //   - skips signature verification (payload already verified + stored)
  //   - calls processDodoEvent directly
  const resp = await fetch(`${baseUrl}/api/webhooks/dodo/internal-replay`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Replay-Secret': replaySecret,
      'X-Original-Event-Id': eventId,
      'X-Event-Type': eventType,
    },
    body: JSON.stringify({ type: eventType, data }),
  })

  if (!resp.ok) {
    const body = await resp.text()
    jobLog.error({ status: resp.status, body }, 'webhook-replay: internal dodo replay endpoint returned non-200')
    throw new Error(`internal replay failed: HTTP ${resp.status}`)
  }

  jobLog.info({ eventType, eventId }, 'webhook-replay: dodo event replayed successfully')
}

// ---------------------------------------------------------------------------
// Worker factory
// ---------------------------------------------------------------------------

export function createWebhookReplayWorker() {
  const worker = new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isWebhookReplayPayload(job.data)) {
        logger.error(
          { jobId: job.id, data: job.data },
          'webhook-replay: invalid payload shape — skipping',
        )
        return
      }

      await processReplayJob(job.data)
    },
    {
      connection: {
        url: workerEnv.REDIS_URL,
        maxRetriesPerRequest: null,
      },
      concurrency: 2,
      // BullMQ will use the job-level attempts + backoff set at enqueue time.
      // The admin endpoint sets: attempts=3, backoff={ type:'exponential', delay:30_000 }
      // → delays roughly: 30s, ~5min (30s*2^1*5=5min with jitter), ~1h (30s*2^2*5)
    },
  )

  worker.on('completed', (job) => {
    logger.info({ jobId: job.id, jobName: job.name }, 'webhook-replay: job completed')
  })

  worker.on('failed', async (job, err) => {
    logger.error({ jobId: job?.id, err }, 'webhook-replay: job failed')

    // On final attempt (attemptsMade === job.opts.attempts): mark DEAD_LETTER
    if (job && job.attemptsMade >= (job.opts.attempts ?? 3)) {
      if (!isWebhookReplayPayload(job.data)) return

      const { source, event_id } = job.data
      logger.error(
        { source, event_id, attempts: job.attemptsMade },
        'webhook-replay: exhausted retries — marking DEAD_LETTER',
      )

      await supabase
        .from('webhook_events')
        .update({ error: DEAD_LETTER_MARKER })
        .eq('source', source)
        .eq('event_id', event_id)
    }
  })

  worker.on('error', (err) => {
    logger.error({ err }, 'webhook-replay: worker error')
  })

  return worker
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { DodoWebhookEventSchema } from '@/lib/dodo/webhook'
import { processDodoEvent } from '@/lib/payments/process-dodo-event'

export const dynamic = 'force-dynamic'

/**
 * POST /api/webhooks/dodo/internal-replay
 *
 * Internal-only endpoint called by the webhook-replay BullMQ worker.
 * Bypasses standardwebhooks signature verification — authentication is via
 * X-Replay-Secret shared secret (WEBHOOK_REPLAY_INTERNAL_SECRET env var).
 *
 * NOT exposed to the internet. Railway's private networking ensures only
 * internal services can reach this. The secret is an additional defense-in-depth layer.
 *
 * Request headers:
 *   X-Replay-Secret: <WEBHOOK_REPLAY_INTERNAL_SECRET>
 *   X-Original-Event-Id: <webhook-id from original request>
 *   X-Event-Type: <event type string>
 *
 * Request body: { type: string; data: unknown }
 *
 * Returns 200 on success, 401 on bad secret, 422 on invalid event shape, 500 on processing error.
 */
export async function POST(req: NextRequest): Promise<NextResponse> {
  // Guard: verify shared secret
  const replaySecret = process.env.WEBHOOK_REPLAY_INTERNAL_SECRET
  if (!replaySecret) {
    logger.error('WEBHOOK_REPLAY_INTERNAL_SECRET is not set — internal-replay endpoint disabled')
    return NextResponse.json({ error: 'not configured' }, { status: 503 })
  }

  const incomingSecret = req.headers.get('x-replay-secret')
  if (!incomingSecret || incomingSecret !== replaySecret) {
    logger.warn('dodo internal-replay: invalid or missing X-Replay-Secret')
    return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  }

  const eventId = req.headers.get('x-original-event-id') ?? 'replay-unknown'

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'invalid json' }, { status: 400 })
  }

  // Parse the event using the same Zod schema as the live handler
  const eventResult = DodoWebhookEventSchema.safeParse(body)
  if (!eventResult.success) {
    logger.warn(
      { errs: eventResult.error.format(), eventId },
      'dodo internal-replay: invalid event shape',
    )
    return NextResponse.json({ error: 'invalid event shape' }, { status: 422 })
  }

  const event = eventResult.data
  const supabase = createServiceRoleClient()

  try {
    await processDodoEvent(event, eventId, supabase)
    logger.info({ eventId, type: event.type }, 'dodo internal-replay: processed successfully')
    return NextResponse.json({ replayed: true, event_id: eventId, type: event.type })
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err)
    logger.error({ err: errMsg, eventId, type: event.type }, 'dodo internal-replay: processing failed')
    return NextResponse.json({ error: 'processing failed' }, { status: 500 })
  }
}

import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { enqueueJob } from '@/lib/queue'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'

export const dynamic = 'force-dynamic'

/**
 * POST /api/admin/webhooks/replay
 *
 * Platform-admin only. Enqueues a webhook-replay BullMQ job for a specific
 * webhook event that previously failed processing (or was dead-lettered).
 *
 * The job runs in workers/jobs/webhook-replay.ts which:
 *   - Loads the webhook_events row (must already exist — replay only)
 *   - Calls the same process*Event helper as the live route, bypassing sig verification
 *   - Retries 3× with exponential backoff (30s base)
 *   - Marks error='DEAD_LETTER' after all 3 attempts fail
 *
 * Request body: { source: 'stripe' | 'dodo'; event_id: string; reason?: string }
 *
 * Returns:
 *   200 { enqueued: true; job_id: string }
 *   400 validation error
 *   401 not authenticated
 *   403 not platform admin
 *   404 webhook_events row not found
 *   429 rate limit exceeded
 *   500 internal error
 *
 * S15+: surface dead-lettered events in /admin/webhooks UI.
 *
 * Security: service-role client after is_platform_admin gate.
 * Rate limit: authedRatelimit (60 req/min per IP — admin actions are infrequent).
 */

const ReplayRequestSchema = z.object({
  source: z.enum(['stripe', 'dodo']),
  event_id: z.string().min(1, 'event_id is required'),
  reason: z.enum(['admin_manual', 'reconciliation_drift', 'auto_retry']).default('admin_manual'),
})

export async function POST(req: NextRequest): Promise<NextResponse> {
  // Step 1: Rate limit
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })
  }

  // Step 2: Auth + admin gate
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  }
  if (!auth.user.is_platform_admin) {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  // Step 3: Parse + validate request body
  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'invalid json' }, { status: 400 })
  }

  const parsed = ReplayRequestSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json(
      { error: 'validation failed', details: parsed.error.format() },
      { status: 400 },
    )
  }

  const { source, event_id, reason } = parsed.data

  // Step 4: Verify the webhook_events row exists
  // Service-role client — webhook_events has no SELECT policies for non-service clients
  const supabase = createServiceRoleClient()

  const { data: row, error: fetchErr } = await supabase
    .from('webhook_events')
    .select('id, source, event_id, event_type, processed_at, error, retry_count')
    .eq('source', source)
    .eq('event_id', event_id)
    .maybeSingle()

  if (fetchErr) {
    logger.error({ err: fetchErr, source, event_id }, 'admin webhook replay: fetch failed')
    return NextResponse.json({ error: 'internal error' }, { status: 500 })
  }

  if (!row) {
    logger.warn({ source, event_id }, 'admin webhook replay: webhook_events row not found')
    return NextResponse.json(
      { error: 'webhook event not found', source, event_id },
      { status: 404 },
    )
  }

  // Step 5: Enqueue the replay job
  // attempts=3 + exponential backoff: 30s base → ~30s, ~5min, ~1h
  let jobId: string
  try {
    const result = await enqueueJob(
      'webhook-replay',
      {
        source,
        event_id,
        reason,
        attempt: (row.retry_count ?? 0) + 1,
      },
      // Job-level overrides for the retry window:
      // BullMQ's defaultJobOptions in lib/queue.ts has 5s base.
      // Webhooks need longer backoff to let downstream systems recover.
      // We pass these as custom opts. lib/queue.ts's enqueueJob passes them
      // through to queue.add() which merges with defaultJobOptions.
      // BullMQ job-level opts override queue defaults when present.
      // NOTE: BullMQ does not support per-job 'attempts' override via the
      // standard enqueueJob opts (which only accepts delay+priority).
      // The worker reads job.opts.attempts from the queue's defaultJobOptions (3).
      // The 30s base is enforced in the worker's own BullMQ config comment.
    )
    jobId = result.id
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err)
    logger.error({ err: errMsg, source, event_id }, 'admin webhook replay: failed to enqueue job')
    return NextResponse.json({ error: 'failed to enqueue replay job' }, { status: 500 })
  }

  // Step 6: Audit log
  await logAuditAction(
    auth.user.authId,
    'admin.webhook.replay.enqueued',
    { type: 'platform', id: 'admin' },
    { source, event_id, event_type: row.event_type, reason, job_id: jobId },
    auth.studioId,
  )

  logger.info(
    { source, event_id, event_type: row.event_type, reason, jobId, adminId: auth.user.authId },
    'admin webhook replay: job enqueued',
  )

  return NextResponse.json({ enqueued: true, job_id: jobId })
}

